<?php
require 'includes/auth_helpers.php'; require 'includes/db.php'; require 'includes/media_helpers.php'; require 'includes/toasts.php'; require_staff_or_admin($pdo);
require_once 'includes/menu_customization_defaults.php';
$id=filter_var($_GET['id']??$_POST['item_id']??null,FILTER_VALIDATE_INT)?:0;
$hasUnitCost=false; try{$pdo->query('SELECT unit_cost FROM menu_items LIMIT 0');$hasUnitCost=true;}catch(PDOException $e){}
$entry=['category_id'=>'','item_kind'=>'item','availability_scope'=>'item_only','name'=>'','description'=>'','price'=>'','image_url'=>'','publish_at'=>'','customizations_json'=>'']; if($hasUnitCost)$entry['unit_cost']=''; $errors=[]; $storedBlob=false; $legacyGroups=[]; $isAvailable=false;
if ($id) { $costColumn=$hasUnitCost?',unit_cost':''; $get=$pdo->prepare("SELECT item_id,category_id,item_kind,availability_scope,name,description,price{$costColumn},image_url,publish_at,customizations_json,is_available,(image_data IS NOT NULL) AS has_blob FROM menu_items WHERE item_id=?"); $get->execute([$id]); $found=$get->fetch(); if (!$found) { http_response_code(404); exit('Menu entry not found.'); } $entry=array_intersect_key($found,$entry); $entry['price']=$found['price']===null?'':(string)$found['price']; if($hasUnitCost)$entry['unit_cost']=$found['unit_cost']===null?'':(string)$found['unit_cost']; $entry['publish_at']=$found['publish_at']?(new DateTimeImmutable((string)$found['publish_at'],new DateTimeZone('Asia/Manila')))->format('Y-m-d\TH:i'):''; $storedBlob=(bool)$found['has_blob']; $isAvailable=(bool)$found['is_available']; $legacyGroups=menuCustomizationDefaults((string)$found['name']); }
$categories=$pdo->query('SELECT category_id,name FROM menu_categories ORDER BY sort_order,name')->fetchAll();
$optionQuery=$pdo->prepare("SELECT item_id,name,price FROM menu_items WHERE is_available=1 AND availability_scope IN ('option_only','item_and_option') AND item_id<>? AND (publish_at IS NULL OR publish_at<=DATE_ADD(UTC_TIMESTAMP(),INTERVAL 8 HOUR)) ORDER BY name"); $optionQuery->execute([$id]); $availableOptions=$optionQuery->fetchAll();

if ($_SERVER['REQUEST_METHOD']==='POST') {
    foreach ($entry as $key=>$_) $entry[$key]=trim((string)($_POST[$key]??''));
    if (!csrf_check($_POST['csrf']??null)) $errors[]='Session expired. Refresh and try again.';
    if (!filter_var($entry['category_id'],FILTER_VALIDATE_INT)||!mb_strlen($entry['name'])||mb_strlen($entry['name'])>255) $errors[]='Choose a category and enter a menu name.';
    if (!in_array($entry['item_kind'],['item','option'],true)) $errors[]='Choose whether this entry is a menu item or an option.';
    $allowedScopes=$entry['item_kind']==='item'?['item_only','item_and_option']:['option_only','item_and_option'];
    if (!in_array($entry['availability_scope'],$allowedScopes,true)) $errors[]='Choose where this entry can be used.';
    if ($entry['price']!==''&&(!is_numeric($entry['price'])||(float)$entry['price']<0||(float)$entry['price']>99999999)) $errors[]='Enter a valid non-negative price.';
    if ($hasUnitCost&&$entry['unit_cost']!==''&&(!is_numeric($entry['unit_cost'])||(float)$entry['unit_cost']<0||(float)$entry['unit_cost']>99999999)) $errors[]='Enter a valid non-negative unit cost.';
    if ($entry['item_kind']==='item'&&($entry['price']===''||(float)$entry['price']<=0)) $errors[]='Menu items need a price greater than zero.';
    if ($entry['image_url']!==''&&!(filter_var($entry['image_url'],FILTER_VALIDATE_URL)&&in_array(strtolower((string)parse_url($entry['image_url'],PHP_URL_SCHEME)),['http','https'],true))) $errors[]='Photo links must use http or https.';
    if ($entry['publish_at']!==''&&!preg_match('/^\d{4}-\d\d-\d\dT\d\d:\d\d$/',$entry['publish_at'])) $errors[]='Choose a valid release date and time.';
    $releaseDate=$entry['publish_at']===''?null:DateTimeImmutable::createFromFormat('!Y-m-d\TH:i',$entry['publish_at'],new DateTimeZone('Asia/Manila')); $dateErrors=DateTimeImmutable::getLastErrors();
    if ($entry['publish_at']!==''&&(!$releaseDate||($dateErrors&&($dateErrors['warning_count']||$dateErrors['error_count'])))) $errors[]='Choose a valid release date and time.';
    $rawGroups=trim((string)($_POST['customizations_json']??'')); $groups=$rawGroups===''?[]:json_decode($rawGroups,true); $customJson=null;
    if ($rawGroups!==''&&(!is_array($groups)||json_last_error()!==JSON_ERROR_NONE||!array_is_list($groups))) $errors[]='Customization groups are not in a valid format.';
    if ($entry['item_kind']==='option'&&is_array($groups)&&$groups) $errors[]='Option entries cannot contain their own customization groups.';
    if ($entry['item_kind']==='item'&&is_array($groups)&&$groups) {
        if (!array_is_list($groups)||count($groups)>12) $errors[]='Customization groups are not in a valid format.';
        $safeGroups=[]; $seenKeys=[];
        foreach ($groups as $groupIndex=>$group) {
            if (!is_array($group)) { $errors[]='Review the customization groups.'; break; }
            $label=trim((string)($group['label']??'')); $key=preg_replace('/[^a-z0-9_-]+/i','-',strtolower($label)); $key=trim((string)$key,'-'); if ($key==='') $key='group-'.($groupIndex+1); if (isset($seenKeys[$key])) $key.='-'.($groupIndex+1); $seenKeys[$key]=true;
            $names=array_values(array_unique(array_filter($group['choices']??[],static fn($name)=>is_string($name)&&$name!=='')));
            if ($label===''||mb_strlen($label)>100||!$names||count($names)>40) { $errors[]='Each customization group needs a label and one or more available options.'; break; }
            $lookups=[]; $lookup=$pdo->prepare("SELECT name,price FROM menu_items WHERE name=? AND is_available=1 AND availability_scope IN ('option_only','item_and_option') AND (publish_at IS NULL OR publish_at<=DATE_ADD(UTC_TIMESTAMP(),INTERVAL 8 HOUR)) LIMIT 1");
            foreach ($names as $name) { $lookup->execute([$name]); if ($row=$lookup->fetch()) $lookups[]=['name'=>$row['name'],'priceCents'=>(int)round((float)($row['price']??0)*100)]; }
            if (count($lookups)!==count($names)) { $errors[]='One selected option is not available. Refresh and choose from active options.'; break; }
            $multiple=($group['multiple']??'')==='1'; $maxCount=filter_var($group['maxCount']??null,FILTER_VALIDATE_INT); if ($multiple&&($maxCount===false||$maxCount<1||$maxCount>99)) { $errors[]='Set a valid maximum quantity for a multiple-choice group.'; break; }
            $safeGroups[]=['key'=>$key,'label'=>$label,'required'=>($group['required']??'')==='1','multiple'=>$multiple,'maxCount'=>$multiple?(int)$maxCount:null,'choices'=>$lookups];
        }
        if (!$errors) $customJson=$safeGroups?json_encode($safeGroups,JSON_UNESCAPED_UNICODE):null;
    }
    if ($entry['item_kind']==='option') $customJson=null;
    try { $photo=uploaded_menu_image($_FILES['image_file']??[]); } catch (Throwable $e) { $photo=null; $errors[]=$e->getMessage(); }
    if (!$errors) {
        $release=$releaseDate?$releaseDate->format('Y-m-d H:i:s'):null; $remove=($_POST['remove_image']??'')==='1';
        $currentUrl=$entry['image_url']?:null; $blobData=$photo['data']??null; $blobMime=$photo['mime']??null;
        if (!$photo&&$id&&!$remove) { $oldUrl=$pdo->prepare('SELECT image_url FROM menu_items WHERE item_id=?'); $oldUrl->execute([$id]); if ($currentUrl===null&&$oldUrl->fetchColumn()===null) $preserveBlob=true; }
        if (!$photo&&$id&&!$remove&&isset($preserveBlob)) { $blobSql='image_data=image_data,image_mime=image_mime'; $url=$currentUrl; }
        elseif ($photo) { $blobSql='image_data=?,image_mime=?'; $url=null; }
        else { $blobSql='image_data=NULL,image_mime=NULL'; if ($remove) $url=null; }
        if ($id) {
            $costSet=$hasUnitCost?',unit_cost=?':''; $sql="UPDATE menu_items SET category_id=?,item_kind=?,availability_scope=?,name=?,description=?,price=?$costSet,image_url=?,publish_at=?,customizations_json=?,$blobSql WHERE item_id=?";
            $params=[(int)$entry['category_id'],$entry['item_kind'],$entry['availability_scope'],$entry['name'],$entry['description']?:null,$entry['price']===''?null:$entry['price']]; if($hasUnitCost)$params[]=$entry['unit_cost']===''?null:$entry['unit_cost']; array_push($params,$url,$release,$customJson); if ($photo) array_push($params,$blobData,$blobMime); $params[]=$id;
        } else {
            $costColumn=$hasUnitCost?',unit_cost':''; $costPlaceholder=$hasUnitCost?',?':''; $sql="INSERT INTO menu_items (category_id,item_kind,availability_scope,name,description,price$costColumn,image_url,image_data,image_mime,publish_at,customizations_json,is_available) VALUES (?,?,?,?,?,?{$costPlaceholder},?,?,?,?,?,0)";
            $params=[(int)$entry['category_id'],$entry['item_kind'],$entry['availability_scope'],$entry['name'],$entry['description']?:null,$entry['price']===''?null:$entry['price']]; if($hasUnitCost)$params[]=$entry['unit_cost']===''?null:$entry['unit_cost']; array_push($params,$photo?null:$currentUrl,$blobData,$blobMime,$release,$customJson);
        }
        try { $pdo->prepare($sql)->execute($params); $_SESSION['flash_success']=$id?'Menu entry updated.':'Menu entry added inactive. An admin must activate it.'; header('Location: menu-management.php'); exit; } catch (Throwable $e) { $errors[]='Could not save the menu entry. Check the category and try again.'; }
    }
}
$optionData=array_map(static fn($option)=>['name'=>$option['name'],'priceCents'=>(int)round((float)($option['price']??0)*100)],$availableOptions);
$initialGroups=json_decode((string)$entry['customizations_json'],true); if (!is_array($initialGroups)) $initialGroups=[]; if ($id&&!$initialGroups&&$entry['item_kind']==='item') $initialGroups=$legacyGroups;
$imageQuery=$id?'menu-image.php?id='.$id:($entry['image_url']?:'assets/menu-placeholder.svg');
$pageTitle=$id?'Edit menu entry':'Add menu entry'; $pageScripts='<script src="assets/js/menu-entry-editor.js"></script><script src="assets/js/image-preview.js"></script>'; require 'includes/header.php'; render_toasts(array_map(static fn($message)=>['kind'=>'danger','text'=>$message],$errors));
?>
